def _git(git: str, *arguments: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [git, *arguments],
        cwd=ROOT,
        text=True,
        encoding="utf-8",
        errors="replace",
        capture_output=True,
        check=False,
    )

def _runtime_parser_identity() -> dict[str, str | None]:
    module = _load_pypdf()
    module_name = str(getattr(module, "__name__", ""))
    distribution_name = module_name.split(".", 1)[0]
    try:
        distribution_version = importlib.metadata.version(distribution_name)
    except importlib.metadata.PackageNotFoundError:
        distribution_version = None
    return {
        "module_name": module_name,
        "module_version": str(getattr(module, "__version__", "")) or None,
        "distribution_name": distribution_name,
        "distribution_version": distribution_version,
    }

def _parser_identity_matches(expected: dict[str, Any], actual: dict[str, Any]) -> bool:
    name = expected.get("name")
    version = expected.get("version")
    return (
        actual.get("module_name") == name
        and actual.get("distribution_name") == name
        and actual.get("module_version") == version
        and actual.get("distribution_version") == version
    )

def _capture_diagnostic(
    diagnostic_id: str,
    operation: Callable[[], object],
    expected_fragment: str,
) -> dict[str, Any]:
    try:
        operation()
    except PdfExtractionError as exc:
        observed = str(exc)
        return {
            "diagnostic_id": diagnostic_id,
            "expected_fragment": expected_fragment,
            "observed": observed,
            "passed": expected_fragment in observed,
        }
    return {
        "diagnostic_id": diagnostic_id,
        "expected_fragment": expected_fragment,
        "observed": "no-error",
        "passed": False,
    }

def _git(repo: Path, *arguments: str) -> str:
    completed = subprocess.run(
        ["git", "-C", str(repo), *arguments],
        text=True,
        encoding="utf-8",
        errors="replace",
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    if completed.returncode:
        raise RuntimeError(
            f"git -C {repo} {' '.join(arguments)} failed with {completed.returncode}: "
            f"{(completed.stderr or completed.stdout).strip()}"
        )
    return completed.stdout.strip()

def _run_ckb(ckb: Path, *arguments: str, environment: dict[str, str] | None = None) -> dict[str, Any]:
    completed = subprocess.run(
        [sys.executable, "-X", "utf8", str(ckb), *arguments],
        text=True,
        encoding="utf-8",
        errors="replace",
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env=environment,
    )
    if completed.returncode:
        raise RuntimeError(
            f"ckb {' '.join(arguments)} failed with {completed.returncode}: "
            f"{(completed.stderr or completed.stdout).strip()}"
        )
    try:
        value = json.loads(completed.stdout)
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"ckb {' '.join(arguments)} returned invalid JSON: {completed.stdout[:500]}") from exc
    if not isinstance(value, dict):
        raise RuntimeError(f"ckb {' '.join(arguments)} did not return one JSON object")
    return value

def _assert_equal(actual: object, expected: object, label: str) -> None:
    if actual != expected:
        raise RuntimeError(f"{label}: expected={expected!r}; actual={actual!r}")

def _assert(condition: bool, label: str) -> None:
    if not condition:
        raise RuntimeError(label)

def _file_evidence(path: Path) -> dict[str, Any]:
    data = path.read_bytes()
    return {
        "path": str(path.resolve()),
        "bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }

def _environment_value(name: str, value: str):
    previous = os.environ.get(name)
    os.environ[name] = value
    try:
        yield
    finally:
        if previous is None:
            os.environ.pop(name, None)
        else:
            os.environ[name] = previous

def cleanup_probe_sessions() -> None:
            for session_id in (skill_session, fallback_session):
                try:
                    close_session(
                        harness="generic",
                        session_id=session_id,
                        output=output,
                        root=session_root,
                        reason="probe-finally",
                        timeout=5,
                    )
                except Exception:
                    pass
            try:
                cleanup_sessions(root=session_root)
            except Exception:
                pass

def git(repo: Path, *args: str) -> None:
    completed = subprocess.run(["git", "-C", str(repo), *args], text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if completed.returncode:
        raise RuntimeError(completed.stderr)
